  const currentSurfaceKey=()=>`${side==='primary'?'dark':'light'}.${garmentView}`;
  const syncPublicHistory=()=>{if(workflowDemo)return;publicState=publicHistory.getState();frontSides.primary=publicState.surfaces['dark.front'];frontSides.reverse=publicState.surfaces['light.front'];backSides.primary=publicState.surfaces['dark.back'];backSides.reverse=publicState.surfaces['light.back'];sides=garmentView==='front'?frontSides:backSides;selectedId=publicState.view.selectedLayerId;d.colour=publicState.palette.primary;d.accent=publicState.palette.secondary;d.third=publicState.palette.accent;d.fourth=publicState.palette.light};
  const dispatchPublic=action=>{const result=publicHistory?.dispatch(action);if(result?.ok)syncPublicHistory();if(result?.persisted===false)persistenceWarning=true;return result};
  const getChecks=()=>workflowDemo?[]:getCustomerDesignChecks(publicState);
